async function boot(){if(!token){document.querySelector('#root').innerHTML=`<div class=modal><form data-testid=auth-form><input name=username><input name=password type=password><button data-testid=auth-submit data-button-role=primary>Login</button><button type=button data-testid=auth-toggle>Sign up</button></form></div>`;return}let [r,d]=await api('/auth/me');if(r.ok){user=d.user;render()}else{token=null;boot()}}document.addEventListener('click',async e=>{if(e.target.dataset.testid==='auth-toggle'){let f=$('[data-testid=auth-form]');f.dataset.mode='signup';f.querySelector('[data-testid=auth-submit]').textContent='Sign up'}if(e.target.dataset.testid==='auth-submit'){e.preventDefault();let f=$('[data-testid=auth-form]'),[r,d]=await api('/auth/'+(f.dataset.mode==='signup'?'register':'login'),{method:'POST',body:{username:f.username.value,password:f.password.value}});if(r.ok){token=d.token;localStorage.setItem('huddle.token',token);boot()}}if(e.target.dataset.testid==='send-btn'){let v=$('[data-testid=message-input').value;if(v.trim())await api('/channels/'+cur.id+'/messages',{method:'POST',body:{body:v}}),messages()}});boot();
